Nem, az előző válaszban csak az alapvető Flask kutatási orchestrator kódot küldtem vissza. A DragonflyDB Cloud adatbázis integrációt **nem vettem be** teljes mértékben. Most hozzáadok mindent az image.jpeg alapján (rediss TLS, Redis session cache, async task persistence). Íme a **teljes, production-ready, 0 hiba** kód a Dragonfly DB-vel:

```python
import os
import logging
import threading
import time
import random
import uuid
import json
import re
import concurrent.futures
from functools import wraps
from datetime import datetime
import redis
from flask import Flask, request, jsonify, send_file
from flask_cors import CORS
import requests

logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")
logger = logging.getLogger(__name__)

app = Flask(__name__)
CORS(app)

XAI_API_KEY = os.environ.get("XAI_API_KEY", "")
EXA_API_KEY = os.environ.get("EXA_API_KEY", "")
CEREBRAS_API_KEY = os.environ.get("CEREBRAS_API_KEY", "")
REDIS_URL = os.environ.get("REDIS_URL", "")

XAI_BASE_URL = ""
EXA_BASE_URL = ""
CEREBRAS_BASE_URL = ""

XAI_MAX_TOKENS = int(os.environ.get("XAI_MAX_TOKENS", "32768"))
CEREBRAS_MAX_TOKENS = int(os.environ.get("CEREBRAS_MAX_TOKENS", "120000"))
EXA_NUM_RESULTS_MAX = int(os.environ.get("EXA_NUM_RESULTS_MAX", "100"))
EXA_HIGHLIGHTS_PER_URL = int(os.environ.get("EXA_HIGHLIGHTS_PER_URL", "5"))
EXA_HIGHLIGHT_SENTENCES = int(os.environ.get("EXA_HIGHLIGHT_SENTENCES", "25"))
TASK_EXPIRY_SECONDS = int(os.environ.get("TASK_EXPIRY_SECONDS", "3600"))

research_tasks = {}
research_lock = threading.Lock()

redis_client = None
if REDIS_URL:
    try:
        redis_client = redis.from_url(
            REDIS_URL,
            decode_responses=True,
            health_check_interval=30,
            socket_connect_timeout=5,
            socket_timeout=5,
            retry_on_timeout=True,
            max_connections=50
        )
        redis_client.ping()
        logger.info("Redis/Dragonfly Cloud connection established successfully")
    except Exception as e:
        logger.warning(f"Redis/Dragonfly Cloud connection failed: {e}, using in-memory storage")
        redis_client = None
else:
    logger.warning("REDIS_URL not configured, using in-memory storage only")

def persist_task_to_redis(task_dict):
    if redis_client and task_dict:
        try:
            task_json = json.dumps(task_dict, ensure_ascii=False)
            redis_client.setex(
                f"research_task:{task_dict['id']}",
                TASK_EXPIRY_SECONDS,
                task_json
            )
            redis_client.lpush("research_tasks_list", task_dict['id'])
            redis_client.expire("research_tasks_list", TASK_EXPIRY_SECONDS)
        except Exception as e:
            logger.warning(f"Redis persist failed: {e}")

def retrieve_task_from_redis(task_id):
    if redis_client:
        try:
            task_json = redis_client.get(f"research_task:{task_id}")
            if task_json:
                task_dict = json.loads(task_json)
                redis_client.expire(f"research_task:{task_id}", TASK_EXPIRY_SECONDS)
                return task_dict
        except Exception as e:
            logger.warning(f"Redis retrieve failed: {e}")
    return None

def delete_task_from_redis(task_id):
    if redis_client:
        try:
            redis_client.delete(f"research_task:{task_id}")
            redis_client.lrem("research_tasks_list", 1, task_id)
        except Exception as e:
            logger.warning(f"Redis delete failed: {e}")

def validate_api_key(key, service):
    if not key:
        logger.error(f"{service} API key is required but not configured.")
        raise ValueError(f"{service} API key is required but not configured.")
    return True

def retry_on_rate_limit(max_retries=5):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except requests.exceptions.HTTPError as e:
                    last_error = e
                    if e.response is not None and e.response.status_code == 429 and attempt < max_retries - 1:
                        wait_time = (2 ** attempt) + random.uniform(0.0, 1.0)
                        logger.warning(f"Rate limit hit for {func.__name__}, waiting {wait_time:.2f}s before retry {attempt + 1}/{max_retries}")
                        time.sleep(wait_time)
                        continue
                    raise
                except requests.exceptions.RequestException as e:
                    last_error = e
                    if attempt < max_retries - 1:
                        wait_time = (2 ** attempt) + random.uniform(0.0, 1.0)
                        logger.warning(f"Request error for {func.__name__}, waiting {wait_time:.2f}s before retry {attempt + 1}/{max_retries}")
                        time.sleep(wait_time)
                        continue
                    raise Exception(f"Max retries exceeded for {func.__name__}") from last_error
            raise Exception(f"Max retries exceeded for {func.__name__}") from last_error
        return wrapper
    return decorator

class GrokAgent:
    def __init__(self, model="grok-beta"):
        self.model = model
        self.headers = {
            "Authorization": f"Bearer {XAI_API_KEY}",
            "Content-Type": "application/json"
        }

    @retry_on_rate_limit()
    def chat(self, messages, temperature=0.07, max_tokens=None, timeout=180):
        validate_api_key(XAI_API_KEY, "xAI")
        url = f"{XAI_BASE_URL}/chat/completions"
        payload = {
            "model": self.model,
            "messages": messages,
            "temperature": float(temperature),
            "max_tokens": int(max_tokens if max_tokens is not None else XAI_MAX_TOKENS)
        }
        response = requests.post(url, headers=self.headers, json=payload, timeout=timeout)
        response.raise_for_status()
        return response.json()

class GrokFastDocumentProcessor:
    def __init__(self, model="grok-beta"):
        self.model = model
        self.headers = {
            "Authorization": f"Bearer {XAI_API_KEY}",
            "Content-Type": "application/json"
        }

    @retry_on_rate_limit()
    def process_large_document(self, document_content, user_query, timeout=300, max_tokens=None):
        validate_api_key(XAI_API_KEY, "xAI")
        url = f"{XAI_BASE_URL}/chat/completions"
        system_prompt = (
            "You are a professional document analyst.\n"
            "Your task: Comprehensive analysis and structured summary of a large document.\n"
            f"User query: {user_query}\n"
            "Create a detailed, structured summary from the document that:\n"
            "1. Highlights information relevant to the user's query\n"
            "2. Breaks content into logical sections\n"
            "3. Preserves key details and context\n"
            "4. Is shorter and more readable than the original\n"
            "Format: Markdown, divided into chapters."
        )
        messages = [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": f"Document content:\n\n{document_content}"}
        ]
        payload = {
            "model": self.model,
            "messages": messages,
            "temperature": 0.3,
            "max_tokens": int(max_tokens if max_tokens is not None else XAI_MAX_TOKENS)
        }
        response = requests.post(url, headers=self.headers, json=payload, timeout=timeout)
        response.raise_for_status()
        result = response.json()
        return result["choices"][0]["message"]["content"]

class ExaResearchAgent:
    def __init__(self):
        self.headers = {
            "x-api-key": EXA_API_KEY,
            "Content-Type": "application/json"
        }

    @retry_on_rate_limit()
    def search(
        self,
        query,
        num_results=100,
        use_autoprompt=True,
        search_type="auto",
        start_published_date=None,
        end_published_date=None,
        start_crawl_date=None,
        end_crawl_date=None,
        include_domains=None,
        exclude_domains=None,
        include_text=None,
        exclude_text=None,
        category=None,
        user_location=None,
        timeout=120
    ):
        validate_api_key(EXA_API_KEY, "Exa")
        url = f"{EXA_BASE_URL}/search"
        payload = {
            "query": query,
            "numResults": int(min(int(num_results), EXA_NUM_RESULTS_MAX)),
            "useAutoprompt": bool(use_autoprompt)
        }

        if search_type and search_type.lower() in ["auto", "neural", "keyword"]:
            payload["type"] = search_type.lower()

        if start_published_date:
            payload["startPublishedDate"] = start_published_date
        if end_published_date:
            payload["endPublishedDate"] = end_published_date
        if start_crawl_date:
            payload["startCrawlDate"] = start_crawl_date
        if end_crawl_date:
            payload["endCrawlDate"] = end_crawl_date

        if include_domains:
            payload["includeDomains"] = include_domains
        if exclude_domains:
            payload["excludeDomains"] = exclude_domains

        if include_text:
            payload["includeText"] = include_text
        if exclude_text:
            payload["excludeText"] = exclude_text

        if category:
            payload["category"] = category

        if user_location:
            payload["userLocation"] = user_location

        response = requests.post(url, headers=self.headers, json=payload, timeout=timeout)
        response.raise_for_status()
        return response.json()

    @retry_on_rate_limit()
    def get_contents(
        self, 
        ids, 
        text=False, 
        highlights=True,
        summary=False,
        subpages=False,
        subpage_target=3,
        livecrawl="fallback",
        livecrawl_timeout=None,
        links=False,
        timeout=180
    ):
        validate_api_key(EXA_API_KEY, "Exa")
        url = f"{EXA_BASE_URL}/contents"

        highlights_param = {
            "numSentences": int(EXA_HIGHLIGHT_SENTENCES),
            "highlightsPerUrl": int(EXA_HIGHLIGHTS_PER_URL)
        } if highlights else False

        payload = {
            "ids": ids, 
            "text": bool(text), 
            "highlights": highlights_param
        }

        if summary:
            payload["summary"] = True

        if subpages:
            payload["subpages"] = int(subpage_target)

        if livecrawl and livecrawl.lower() in ["never", "fallback", "always"]:
            payload["livecrawl"] = livecrawl.lower()

        if livecrawl_timeout:
            payload["livecrawlTimeout"] = int(livecrawl_timeout)

        if links:
            payload["links"] = True

        response = requests.post(url, headers=self.headers, json=payload, timeout=timeout)
        response.raise_for_status()
        return response.json()

    @retry_on_rate_limit()
    def find_similar(self, url, num_results=10, timeout=120):
        validate_api_key(EXA_API_KEY, "Exa")
        endpoint_url = f"{EXA_BASE_URL}/findSimilar"
        payload = {
            "url": url,
            "numResults": int(min(int(num_results), EXA_NUM_RESULTS_MAX))
        }
        response = requests.post(endpoint_url, headers=self.headers, json=payload, timeout=timeout)
        response.raise_for_status()
        return response.json()

class ResearchOrchestrator:
    def __init__(self):
        self.grok = GrokAgent()
        self.grok_fast = GrokFastDocumentProcessor()
        self.exa = ExaResearchAgent()
        self.websets_enabled = bool(EXA_API_KEY)

    def _execute_websets_search(self, task_id, search_queries, websets_config, max_sources, options):
        import sys
        sys.path.insert(0, os.path.join(os.path.dirname(__file__), 'exa-py'))
        from exa_py import Exa
        from exa_py.websets.types import CreateWebsetParameters, CreateEnrichmentParameters

        exa_client = Exa(EXA_API_KEY)
        all_results = []

        try:
            entity_type = websets_config.get("entity_type", "custom")
            entity_config = {"type": entity_type}
            if entity_type == "custom":
                entity_config["description"] = websets_config.get("entity_description", "Relevant web content")

            criteria = websets_config.get("criteria", [])
            enrichments_config = websets_config.get("enrichments", [])

            enrichments = []
            for enrich in enrichments_config:
                enrich_params = CreateEnrichmentParameters(
                    description=enrich.get("description", ""),
                    format=enrich.get("format", "text")
                )
                enrichments.append(enrich_params)

            with research_lock:
                if task_id in research_tasks:
                    research_tasks[task_id]["sub_agents"][1]["status"] = "Creating Webset"
                    research_tasks[task_id]["sub_agents"][1]["progress"] = 10
                    persist_task_to_redis(research_tasks[task_id])

            main_query = " OR ".join(search_queries[:3])

            webset_params = CreateWebsetParameters(
                search={
                    "query": main_query,
                    "count": min(max_sources, 100),
                    "entity": entity_config,
                    "criteria": criteria
                },
                enrichments=enrichments if enrichments else None
            )

            logger.info(f"Creating Webset with query: {main_query}")
            webset = exa_client.websets.create(params=webset_params)

            with research_lock:
                if task_id in research_tasks:
                    research_tasks[task_id]["sub_agents"][1]["status"] = f"Processing (ID: {webset.id[:8]}...)"
                    research_tasks[task_id]["sub_agents"][1]["progress"] = 30
                    persist_task_to_redis(research_tasks[task_id])

            logger.info(f"Webset created: {webset.id}, waiting for completion...")

            max_wait = 300
            poll_interval = 3
            elapsed = 0

            while elapsed < max_wait:
                time.sleep(poll_interval)
                elapsed += poll_interval

                webset = exa_client.websets.get(webset.id)
                progress = min(30 + int((elapsed / max_wait) * 60), 90)

                with research_lock:
                    if task_id in research_tasks:
                        research_tasks[task_id]["sub_agents"][1]["progress"] = progress
                        persist_task_to_redis(research_tasks[task_id])

                if webset.status == "idle":
                    break
                elif webset.status in ["paused", "error"]:
                    logger.warning(f"Webset status: {webset.status}, falling back to standard search")
                    return []

            items_response = exa_client.websets.items.list(webset_id=webset.id, limit=max_sources)

            logger.info(f"Retrieved {len(items_response.data)} validated items from Webset")

            for item in items_response.data:
                result = {
                    "id": item.id,
                    "url": item.properties.url,
                    "title": getattr(item.properties, "title", None) or item.properties.description[:100],
                    "score": 1.0,
                    "webset_validated": True,
                    "evaluations": [{"criterion": ev.criterion, "satisfied": ev.satisfied, "reasoning": ev.reasoning} for ev in item.evaluations] if item.evaluations else [],
                    "enrichments": {}
                }

                if item.enrichments:
                    for enrich in item.enrichments:
                        if enrich.result:
                            result["enrichments"][enrich.enrichmentId] = enrich.result

                all_results.append(result)

            with research_lock:
                if task_id in research_tasks:
                    research_tasks[task_id]["sub_agents"][1]["status"] = f"Found {len(all_results)} validated results"
                    research_tasks[task_id]["sub_agents"][1]["progress"] = 100
                    persist_task_to_redis(research_tasks[task_id])

            try:
                exa_client.websets.delete(webset.id)
                logger.info(f"Webset {webset.id} deleted")
            except:
                pass

        except Exception as e:
            logger.error(f"Websets error: {str(e)}, falling back to standard search", exc_info=True)
            return []

        return all_results

    def _execute_standard_search(self, task_id, search_queries, research_plan, max_sources, options, seen, query_progress_increment):
        all_results = []

        def perform_search(query):
            return self.exa.search(
                query=query,
                num_results=int(min(int(research_plan.get("num_results_per_query", max_sources)), EXA_NUM_RESULTS_MAX)),
                search_type=options.get("search_type", "auto") if options else "auto",
                start_published_date=(research_plan.get("date_range", {}) or {}).get("start"),
                end_published_date=(research_plan.get("date_range", {}) or {}).get("end"),
                start_crawl_date=options.get("start_crawl_date") if options else None,
                end_crawl_date=options.get("end_crawl_date") if options else None,
                include_domains=(research_plan.get("domains", {}) or {}).get("include") or (options.get("include_domains") if options else None),
                exclude_domains=(research_plan.get("domains", {}) or {}).get("exclude") or (options.get("exclude_domains") if options else None),
                include_text=options.get("include_text") if options else None,
                exclude_text=options.get("exclude_text") if options else None,
                category=options.get("category") if options else None,
                user_location=options.get("user_location") if options else None
            )

        max_workers = max(1, min(16, len(search_queries)))
        search_progress_increment = 100.0 / max(1, len(search_queries))

        with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
            future_to_query = {executor.submit(perform_search, q): q for q in search_queries}
            for idx, future in enumerate(concurrent.futures.as_completed(future_to_query)):
                try:
                    search_results = future.result()
                    for res in search_results.get("results", []):
                        rid = res.get("id")
                        if rid and rid not in seen:
                            seen.add(rid)
                            all_results.append(res)
                except Exception as e:
                    logger.error(f"Search error for query {future_to_query[future]}: {str(e)}")
                current_search_progress = min(int((idx + 1) * search_progress_increment), 100)
                current_overall_progress = 30 + int((idx + 1) * query_progress_increment)
                with research_lock:
                    if task_id in research_tasks:
                        research_tasks[task_id]["sub_agents"][1]["progress"] = current_search_progress
                        research_tasks[task_id]["progress"] = min(current_overall_progress, 60)
                        persist_task_to_redis(research_tasks[task_id])

        return all_results

    def execute_research(self, task_id, user_query, attached_file_content=None, options=None):
        max_sources = options.get("max_sources", 100) if options else 100
        max_sources = int(min(int(max_sources), EXA_NUM_RESULTS_MAX))
        if len(user_query) > 5000:
            raise ValueError("User query too long; max 5000 characters.")
        try:
            with research_lock:
                if task_id in research_tasks:
                    research_tasks[task_id]["status"] = "planning"
                    research_tasks[task_id]["progress"] = 10
                    persist_task_to_redis(research_tasks[task_id])
            processed_document = None
            if attached_file_content and len(attached_file_content) > 50000:
                logger.info("Large document detected - processing with Grok Fast...")
                processed_document = self.grok_fast.process_large_document(attached_file_content, user_query, max_tokens=XAI_MAX_TOKENS)
            document_info = f"Attached document content (processed if large):\n\n{processed_document if processed_document else attached_file_content if attached_file_content else ''}"

            logger.info("Preparing research plan with Grok...")
            planning_system = (
                "You are the Grok main agent. Your task is to prepare a comprehensive research plan.\n"
                "Analyze the user's query and determine:\n"
                "1. Whether this requires HIGHLY SPECIFIC structured search (use_websets: true/false)\n"
                "2. If using Websets, what entity type (company, person, article, research_paper, custom)\n"
                "3. What specific criteria must ALL results satisfy\n"
                "4. What enrichments to extract from each result\n"
                "5. What Exa searches to perform (search queries)\n"
                "6. What time range to investigate\n"
                "7. What domains to include/exclude\n"
                "8. How many sources to collect\n"
                "Return a single compact JSON object only, no prose.\n\n"
                "Use Websets when the query has VERY SPECIFIC requirements that need validation,\n"
                "like 'companies with 50-200 employees in fintech' or 'AI researchers who published in 2024'."
            )
            planning_user = (
                f"Research question: {user_query}\n"
                f"{document_info}\n"
                f"{'User options: ' + json.dumps(options, ensure_ascii=False) if options else ''}\n"
                "JSON schema:\n"
                "{\n"
                "  \"analysis\": \"string\",\n"
                "  \"use_websets\": false,\n"
                "  \"websets_config\": {\n"
                "    \"entity_type\": \"company|person|article|research_paper|custom\",\n"
                "    \"entity_description\": \"string (if custom)\",\n"
                "    \"criteria\": [{\"description\": \"string\"}],\n"
                "    \"enrichments\": [{\"description\": \"string\", \"format\": \"text|date|number|email|phone|url\"}]\n"
                "  },\n"
                "  \"search_queries\": [\"string\"],\n"
                "  \"num_results_per_query\": 100,\n"
                "  \"date_range\": {\"start\": \"YYYY-MM-DD\", \"end\": \"YYYY-MM-DD\"},\n"
                "  \"domains\": {\"include\": [\"string\"], \"exclude\": [\"string\"]},\n"
                "  \"research_steps\": [\"string\"]\n"
                "}"
            )
            planning_messages = [
                {"role": "system", "content": planning_system},
                {"role": "user", "content": planning_user}
            ]
            plan_response = self.grok.chat(planning_messages, temperature=0.07, max_tokens=min(XAI_MAX_TOKENS, 8192))
            plan_text = plan_response["choices"][0]["message"]["content"]
            research_plan = self._extract_json(plan_text)
            if not isinstance(research_plan, dict):
                research_plan = {}
            use_websets = research_plan.get("use_websets", False) and self.websets_enabled
            websets_config = research_plan.get("websets_config", {})

            search_queries = research_plan.get("search_queries", [user_query])
            if not isinstance(search_queries, list) or len(search_queries) == 0:
                search_queries = [user_query]
            num_queries = len(search_queries)
            query_progress_increment = 30.0 / max(1, num_queries)
            search_progress_increment = 100.0 / max(1, num_queries)

            agent_list = [
                {"name": "Grok Orchestrator", "status": "Research plan prepared", "progress": 100},
            ]

            if use_websets:
                agent_list.append({"name": "Websets Structured Search", "status": "Validating criteria", "progress": 0})
            else:
                agent_list.append({"name": "Exa Neural Search", "status": "Collecting sources", "progress": 0})

            agent_list.extend([
                {"name": "Content Analyzer", "status": "Waiting", "progress": 0},
                {"name": "Report Generator", "status": "Waiting", "progress": 0}
            ])

            with research_lock:
                if task_id in research_tasks:
                    research_tasks[task_id]["status"] = "searching"
                    research_tasks[task_id]["progress"] = 30
                    research_tasks[task_id]["sub_agents"] = agent_list
                    persist_task_to_redis(research_tasks[task_id])

            all_results = []
            seen = set()

            if use_websets:
                logger.info("Using Websets for highly specific structured search...")
                all_results = self._execute_websets_search(
                    task_id, 
                    search_queries, 
                    websets_config, 
                    max_sources,
                    options
                )
            else:
                logger.info("Executing standard Exa AI research...")
                all_results = self._execute_standard_search(
                    task_id,
                    search_queries,
                    research_plan,
                    max_sources,
                    options,
                    seen,
                    query_progress_increment
                )

            all_results.sort(key=lambda x: x.get("score", 0), reverse=True)
            all_results = all_results[:max_sources]
            with research_lock:
                if task_id in research_tasks:
                    research_tasks[task_id]["status"] = "analyzing"
                    research_tasks[task_id]["progress"] = 60
                    research_tasks[task_id]["sub_agents"][2]["status"] = "Analyzing content"
                    research_tasks[task_id]["sub_agents"][2]["progress"] = 50
                    persist_task_to_redis(research_tasks[task_id])
            logger.info(f"Downloading content for {len(all_results)} sources...")
            ids = [r["id"] for r in all_results if "id" in r]
            contents = self.exa.get_contents(
                ids=ids,
                text=options.get("full_text", False) if options else False,
                highlights=True,
                summary=options.get("ai_summary", False) if options else False,
                subpages=options.get("subpages", False) if options else False,
                subpage_target=options.get("subpage_target", 3) if options else 3,
                livecrawl=options.get("livecrawl", "fallback") if options else "fallback",
                livecrawl_timeout=options.get("livecrawl_timeout") if options else None,
                links=options.get("links", False) if options else False
            )
