                }
                for id_, content in contents_data.items()
            }
            with research_lock:
                if task_id in research_tasks:
                    research_tasks[task_id]["sources"] = all_results
                    research_tasks[task_id]["sub_agents"][2]["progress"] = 100
                    research_tasks[task_id]["progress"] = 75
                    research_tasks[task_id]["status"] = "generating_report"
                    research_tasks[task_id]["sub_agents"][3]["status"] = "Generating report"
                    research_tasks[task_id]["sub_agents"][3]["progress"] = 50
                    persist_task_to_redis(research_tasks[task_id])
            logger.info("Generating final report with Grok...")
            document_synthesis_info = f"Attached document content (processed if large):\n\n{processed_document if processed_document else attached_file_content if attached_file_content else ''}"
            synthesis_system = (
                "You are the Grok main agent. Prepare a detailed, comprehensive research report.\n"
                "The report should include:\n"
                "1. Executive Summary\n"
                "2. Methodology (what sources were used)\n"
                "3. Key Findings (divided into sections)\n"
                "4. Conclusions\n"
                "5. Sources list\n"
                "Format: Markdown, professional style, detailed."
            )
            synthesis_user = (
