                max_sources = EXA_NUM_RESULTS_MAX

            category = request.form.get("category", None)
            search_type = request.form.get("search_type", "auto")
            user_location = request.form.get("user_location", None)
            start_published_date = request.form.get("start_published_date", None)
            end_published_date = request.form.get("end_published_date", None)
            start_crawl_date = request.form.get("start_crawl_date", None)
            end_crawl_date = request.form.get("end_crawl_date", None)
            include_domains = request.form.get("include_domains", None)
            exclude_domains = request.form.get("exclude_domains", None)
            include_text = request.form.get("include_text", None)
            exclude_text = request.form.get("exclude_text", None)
            full_text = request.form.get("full_text", "false").lower() == "true"
            ai_summary = request.form.get("ai_summary", "false").lower() == "true"
            subpages = request.form.get("subpages", "false").lower() == "true"
            subpage_target = int(request.form.get("subpage_target", 3))
            livecrawl = request.form.get("livecrawl", "fallback")
            livecrawl_timeout = request.form.get("livecrawl_timeout", None)
            links = request.form.get("links", "false").lower() == "true"
        else:
            data = request.json or {}
            user_query = (data.get("goal", "") or "").strip()
            max_sources = int(data.get("max_sources", EXA_NUM_RESULTS_MAX))

            category = data.get("category", None)
            search_type = data.get("search_type", "auto")
            user_location = data.get("user_location", None)
            start_published_date = data.get("start_published_date", None)
            end_published_date = data.get("end_published_date", None)
            start_crawl_date = data.get("start_crawl_date", None)
            end_crawl_date = data.get("end_crawl_date", None)
            include_domains = data.get("include_domains", None)
            exclude_domains = data.get("exclude_domains", None)
            include_text = data.get("include_text", None)
            exclude_text = data.get("exclude_text", None)
            full_text = data.get("full_text", False)
            ai_summary = data.get("ai_summary", False)
            subpages = data.get("subpages", False)
            subpage_target = int(data.get("subpage_target", 3))
            livecrawl = data.get("livecrawl", "fallback")
            livecrawl_timeout = data.get("livecrawl_timeout", None)
            links = data.get("links", False)
        if not user_query:
            return jsonify({"error": "Goal is required"}), 400
        attached_file_content = None
        if "file" in request.files and request.files["file"].filename != "":
            file = request.files["file"]
            try:
                attached_file_content = file.read().decode("utf-8", errors="ignore")
            except Exception as e:
                logger.error(f"Error reading uploaded file: {str(e)}")
                return jsonify({"error": "Failed to read uploaded file"}), 400
        task_id = str(uuid.uuid4())
        with research_lock:
            research_tasks[task_id] = {
                "id": task_id,
                "goal": user_query,
                "status": "starting",
                "progress": 0,
                "sub_agents": [],
                "sources": [],
                "report": "",
                "updates": [],
                "error": None,
                "supermemory_stored": False,
                "created_at": datetime.utcnow().isoformat()
            }
            persist_task_to_redis(research_tasks[task_id])
        def run_research():
            try:
                orchestrator.execute_research(
                    task_id=task_id,
                    user_query=user_query,
                    attached_file_content=attached_file_content,
                    options={
                        "max_sources": max_sources,
                        "category": category,
                        "search_type": search_type,
                        "user_location": user_location,
                        "start_published_date": start_published_date,
                        "end_published_date": end_published_date,
                        "start_crawl_date": start_crawl_date,
                        "end_crawl_date": end_crawl_date,
                        "include_domains": include_domains,
                        "exclude_domains": exclude_domains,
                        "include_text": include_text,
                        "exclude_text": exclude_text,
                        "full_text": full_text,
                        "ai_summary": ai_summary,
                        "subpages": subpages,
                        "subpage_target": subpage_target,
                        "livecrawl": livecrawl,
                        "livecrawl_timeout": livecrawl_timeout,
                        "links": links
                    }
                )
                logger.info(f"Research {task_id} completed or ended")
            except Exception as e:
                logger.error(f"Thread error for {task_id}: {str(e)}", exc_info=True)
                with research_lock:
                    if task_id in research_tasks:
                        research_tasks[task_id]["status"] = "error"
                        research_tasks[task_id]["error"] = str(e)
                        persist_task_to_redis(research_tasks[task_id])
        thread = threading.Thread(target=run_research, name=f"research-{task_id}")
        thread.daemon = True
        thread.start()
        return jsonify({"task_id": task_id}), 201
    except Exception as e:
        logger.error(f"Create research error: {str(e)}")
        return jsonify({"error": str(e)}), 500

@app.route("/api/research/<task_id>", methods=["GET"])
def get_research_status(task_id):
    try:
        task = None
        with research_lock:
            task = research_tasks.get(task_id)

        if not task:
            task = retrieve_task_from_redis(task_id)

        if not task:
            return jsonify({"error": "Task not found"}), 404

        task_copy = dict(task)
        task_copy["updates"] = list(task_copy.get("updates", []))

        return jsonify({
            "task_id": task_id,
            "status": task_copy["status"],
            "progress": task_copy["progress"],
            "sub_agents": task_copy["sub_agents"],
            "sources": task_copy["sources"],
            "report": task_copy["report"],
            "updates": task_copy["updates"],
            "error": task_copy["error"],
            "supermemory_stored": task_copy.get("supermemory_stored", False)
        })
    except Exception as e:
        logger.error(f"Get research status error: {str(e)}")
        return jsonify({"error": str(e)}), 500

@app.route("/api/research/<task_id>/update", methods=["POST"])
def update_research(task_id):
    try:
        data = request.json or {}
        instructions = (data.get("instructions", "") or "").strip()
        if not instructions:
            return jsonify({"error": "Instructions are required"}), 400
        with research_lock:
            task = research_tasks.get(task_id)
            if not task:
                task = retrieve_task_from_redis(task_id)
            if not task:
                return jsonify({"error": "Task not found"}), 404
            if "updates" not in task or not isinstance(task.get("updates"), list):
                task["updates"] = []
            task["updates"].append({
                "instructions": instructions,
                "timestamp": datetime.utcnow().isoformat()
            })
            if task_id in research_tasks:
                research_tasks[task_id] = task
            persist_task_to_redis(task)
        logger.info(f"Update received for task {task_id}")
        return jsonify({"success": True, "message": "Research update received and stored"})
    except Exception as e:
        logger.error(f"Update research error: {str(e)}")
        return jsonify({"error": str(e)}), 500

